reproduced=[];invcheck=[]
for oldr in old:
 gen=oldr['generation'];r=g.generate('easy',seed=gen['seed'],template=gen['template'],parameters=gen['parameters']);q=next(q for q in inv['questions'] if q[':question/id']==r['question'][':question/id'])
 assert r['question'][':question/problem']==q[':question/problem']
 # Canonical math choices/key, not storage entity structure or reordered banks.
 f=q[':question/answer-fields'][0];rf=r['question'][':question/answer-fields'][0];assert sorted(a[':answer/value'] for a in f[':answer-field/choices'])==sorted(a[':answer/value'] for a in rf[':answer-field/choices']);assert f[':answer-field/correct'][':answer/id']==rf[':answer-field/correct'][1]
