def parts(r):
 rr=v.rows(r['question']);A,b=s.linear_eq_to_matrix(rr,[v.x,v.y]);f=r['question'][':question/answer-fields'][0];options=[(v.expr(a[':answer/value'].split('=')[1]),a[':answer/id']) for a in f[':answer-field/choices']];return A,options,f[':answer-field/correct'][1]
def shortcut(r):
 A,options,correct=parts(r);sign=s.sign(A[1,0]*A[0,1]/A[0,0]);picked=(max if sign>0 else min)(options,key=lambda z:z[0]);return picked[1]==correct
probes=[]
