  if selected:probes.append({'cue':'Signs only of the first-row y coefficient and second-row x coefficient; extremal answer position in numeric order','subgroup':label+':'+subgroup,'scope':'within_template' if subgroup=='all' else 'other_recognizable_subgroup','strategy':'If signs agree choose largest positive option, otherwise choose most negative option; ignore all coefficient magnitudes and constants.','correct':sum(shortcut(r) for r in selected),'total':len(selected),'baseline':0.2,'disposition':'defect','conclusion':'Five-choice blind baseline is 1/5. Complete success follows from fixed bank {t,-t,b,-b,0}, a=u=1, |d|>1, so |t|>|b|. This computes no product magnitude or zero-row criterion. The source bank q-32245 has a same-method counterexample (correct -2, distractor -4), showing this is incidental to the bank construction.','sample_refs':refs})
