 pool=[r for r in samples if r['generation']['template']==t];counts=collections.Counter(v.audit(r)['correct_position'] for r in pool);pos,n=counts.most_common(1)[0]
 probes.append({'cue':'Fixed answer position','subgroup':t,'scope':'within_template','strategy':f'Choose stored choice index {pos}; best observed fixed index (exploratory).','correct':n,'total':len(pool),'baseline':0.2,'disposition':'not_predictive','conclusion':'Blind five-choice baseline .2. Small n=8 exploratory position counts do not establish predictive reliability; actual UI also shuffles options.','sample_refs':['samples.json']})
