write('inventory-audit.json',{'basis':inv['basis'],'total_questions':len(inv['questions']),'original_source_questions':17,'reproduced_generated':invcheck,'tested_weakness':'Sign-only extremal-choice shortcut','limitations':['No original source was classified as generated. Missing source family and excluded zero-root cases are generator coverage failures, not stored-item mathematical defects.']})
write('affected-inventory.json',{'affected_questions':[{'question_id':z['question_id'],'entity_id':z['entity_id'],'finding':'Easy answer bank permits sign-only extremal-choice shortcut; coefficient magnitudes and zero-row calculation can be skipped.','reproduction':f"{v.PY} -B variation.py; generated-records.json seed="+str(next(r['generation']['seed'] for r in reproduced if r['question'][':question/id']==z['question_id'])),'evidence_path':'generated-records.json'} for z in invcheck]})
