selection=[]
for seen_n in [0,5,8]:
 candidates=pool[seen_n:];drawn=[]
 for n in range(64):
  seed=f'reviewer-932401-{n}';dig=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest();u=(int.from_bytes(dig[8:16],'big')>>11)/(1<<53);drawn.append(candidates[int(u*len(candidates))])
 selection.append({'seen_prefix':seen_n,'candidate_count':len(candidates),'draws':64,'shortcut_successes':sum(shortcut(r) for r in drawn),'unique_selected':len({r['question'][':question/id'] for r in drawn}),'ordered_candidate_ids':[r['question'][':question/id'] for r in candidates]})
write('selection-results.json',{'source':'engine/rust/question_selection.rs select, seen_before_task; inspected read-only','distribution_basis':'All 10 easy candidates at captured basis plus accepted batch; easy-band draw conditional on easy having positive configured weight. New records assigned append order only (no real entity IDs exist).','cases':selection,'limits':['Actual policy distribution and learner history were not supplied; conditional outcomes only. Any nonempty easy subset has the shortcut, irrespective of IDs, order, weights or history. Unconfigured first-candidate fallback also preserves it.']})
